    facts:[["Working company name","Frontier Orbital Lines <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Formation","Around 1985 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Working founder","Konrad Elias Voss <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Corporate type","Licensed private orbital carrier"],["Principal role","Operator and mission integrator, not primary national manufacturer <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Initial equipment","Older government spaceplanes <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Principal port","Orbital Port Columbia"],["Working charter","National Orbital Carrier · 1993 <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Operating systems","Spaceplanes, reusable boosters, tugs, tankers, depots, and annex facilities"],["Mars role","Principal carrier and mission integrator"],["First American Mars crew","1999 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Mature market position","Functional monopoly by 2000 <sup class='canon-note' data-provenance='a'>[a]</sup>"],["Public relationship","Licensed, strategically protected, reservable, and subject to emergency control"],["Status by 2012","Principal American commercial orbital carrier"]]
